detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What distance metric should be used to compute travel distances between the depot and customers, and between customers — Euclidean straight-line distance, Manhattan (rectilinear) distance, or some other convention?"
  ],
  "rationale": "The response asks for a single policy choice regarding the distance metric, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the travel speed (or travel time) between two points, given their coordinates — for example, is travel time equal to the Euclidean distance in minutes, or is there a specific speed or scaling factor I should use?"
  ],
  "rationale": "The response asks for a single piece of information: the method or factor used to calculate travel time/speed between coordinates. Although it offers examples, it seeks one specific policy or parameter."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Do all 5 trucks start at the depot at time 0?",
    "Must they return to the depot after completing their route, or is there any flexibility in start time or in whether vehicles must return to the depot?"
  ],
  "rationale": "The response asks two distinct policy questions: one regarding the fixed start time/location and another regarding the requirement to return to the depot (and associated flexibility). A user could confirm the start time without addressing the return requirement, or vice versa."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a truck finishes serving its last customer, must it return to the depot within the depot's operating window of [0, 1236] minutes, or is there no deadline on the return arrival time?"
  ],
  "rationale": "The response asks a single clarification question regarding the deadline for the truck's return to the depot."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Is the total demand of all 20 customers (430 units) required to be served by at most 5 trucks, meaning some trucks may carry multiple customers on one route?",
    "Could a single customer's demand ever be split across multiple trucks?"
  ],
  "rationale": "The response contains two semantically independent questions: one asking about the truck capacity/routing constraint (whether 5 trucks must serve all demand) and another asking about the split-delivery policy (whether a single customer's demand can be divided)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a truck visit the same customer more than once, or is each customer visited exactly once by exactly one truck?"
  ],
  "rationale": "The response asks for a single policy choice regarding visit frequency and exclusivity, which constitutes one independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a truck arrives at a customer before the customer's time window opens, it waits until the window opens — is the waiting time counted as part of the truck's schedule (i.e., the truck is occupied and cannot serve another customer during the wait), or is waiting free and the truck could theoretically be elsewhere?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding how waiting time is treated in the truck's schedule."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the service duration of 90 minutes the time from when the truck arrives (or starts waiting) until it departs, or is it the time from when service actually begins (i.e., after any waiting) until the truck departs?"
  ],
  "rationale": "The response asks for a single policy definition regarding the start point of the 90-minute service duration, presenting two mutually exclusive options for one specific parameter."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are all 5 trucks identical in capacity (200 units each) and available for the full operating window, or do any trucks have different capacities or availability restrictions?"
  ],
  "rationale": "The response asks a single clarification question regarding truck uniformity and availability, presented as one compound alternative."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "is there any additional constraint on the number of customers a single truck can serve on one route, or is the only per-route limit the 200-unit capacity?"
  ],
  "rationale": "The response asks a single clarification question regarding whether there are additional per-route constraints beyond the capacity limit."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The objective is to minimize total distance traveled by all vehicles — does this include the distance from the depot to the first customer and from the last customer back to the depot, or only the distances between customers on each route?"
  ],
  "rationale": "The response asks for a single policy choice regarding the definition of total distance (including depot legs vs. excluding them), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a maximum route duration or maximum number of customers per route, or is the only constraint on each route the 200-unit capacity limit?"
  ],
  "rationale": "The response asks a single clarification question regarding route constraints, presenting a choice between additional limits and a single capacity limit."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the coordinates in the table in the same units as the distance used in the objective, so that the objective is simply the sum of Euclidean (or Manhattan) distances between consecutive points on each route, with no additional scaling?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of unit consistency and the specific distance metric definition."
}

