  "is_atomic": true,
  "atomic_questions": [
    "For the time-window feasibility check, is travel time between two points computed using the same distance metric as the objective (i.e., distance in coordinate units equals travel time in minutes), or is there a separate travel-time formula?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding how travel time is calculated relative to the distance metric."
}

{
  "action": "question",
